create table incident (id uuid primary key, organization_id uuid not null references organization(id) on delete cascade, title varchar(180) not null, status varchar(30) not null, severity varchar(20) not null, created_at timestamp with time zone not null, created_by uuid not null references app_user(id));
create table lot_quarantine (id uuid primary key, incident_id uuid not null references incident(id) on delete cascade, lot_id uuid not null references inventory_lot(id), active boolean not null default true, reason varchar(500), created_at timestamp with time zone not null, released_at timestamp with time zone, unique(incident_id,lot_id));
create table corrective_action (id uuid primary key, incident_id uuid not null references incident(id) on delete cascade, description varchar(500) not null, completed boolean not null default false, created_at timestamp with time zone not null, completed_at timestamp with time zone);
